    {
      "type": "monetary_policy",
      "target": null,
      "amount": 0.25,
      "sub": "",
      "order": "Increase policy rate by 0.25 percentage points to cool inflation."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 2.5,
      "sub": "military",
      "order": "Increase military spending slightly to 2.5% of GDP to address emerging security challenges."
    },
    {
      "type": "invest_research",
      "target": null,
      "amount": 0.5,
      "sub": "",
      "order": "Invest an additional 0.5% of GDP into research and development to boost productivity and growth."
    }
  ],
  "cables": [
    {
      "to": "USA",
      "private": true,
      "text": "Reaffirming our steadfast commitment to the NATO alliance and transatlantic security in light of growing regional threats."
    },
    {
      "to": "UKR",
      "private": true,
      "text": "The United Kingdom remains steadfast in its diplomatic and security support for your sovereignty and territorial integrity."
    }
  ],
  "public_statement": "The Government is committed to strengthening our economy, supporting working families, and ensuring our national security against external threats while upholding our proud democratic traditions.",
